4	async function readStdin(): Promise<string> {
5	  const chunks: Buffer[] = [];
6	  for await (const chunk of process.stdin) {
7	    chunks.push(chunk as Buffer);
8	  }
9	  return Buffer.concat(chunks).toString('utf8');
10	}
11	
12	async function main(): Promise<void> {
13	  const scenario = JSON.parse(await readStdin()) as Scenario;
14	  process.stdout.write(JSON.stringify(runScenario(scenario)));
15	}
16	
17	main().catch((error: unknown) => {
18	  process.stderr.write(`${(error as Error).message}\n`);
19	  process.exit(1);
20	});
